style.css:
@-moz-document domain("open.spotify.com") {
/* Background */
    body, .Root__top-container {
        background: #ffb6c1 !important; /* Light pink */
    }

    /* Sidebar */
    .Root__nav-bar {
        background: #ff69b4 !important; /* Hot pink */
    }

    /* Text color */
    .Root__nav-bar a, .Root__nav-bar .Button {
        color: white !important;
    }

    /* Play bar */
    .Root__now-playing-bar {
        background: #ff69b4 !important; /* Hot pink */
    }

    /* Buttons */
    .Button, .control-button {
        color: white !important;
        background: #ff69b4 !important;
        border-radius: 10px !important;
    }

    /* Hover effects */
    .Button:hover, .control-button:hover {
        background: #ff1493 !important; /* Deep pink */
    }

    /* Song progress bar */
    .progress-bar__bg {
        background: #ffb6c1 !important;
    }

    .progress-bar__fg {
        background: #ff1493 !important;
    }
}
